<?php require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/functions.php'; $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){try{register_user($_POST['name']??'',$_POST['email']??'',$_POST['password']??''); login_user($_POST['email']??'',$_POST['password']??''); header('Location: /dashboard.php'); exit;}catch(Throwable $e){$error='Registration failed. Email may already exist.';}} ?>
<!doctype html><html><head><title>Register</title><link rel="stylesheet" href="/assets/css/style.css"></head><body><main class="container"><div class="card"><h1>Create account</h1><?php if($error): ?><div class="alert"><?= e($error) ?></div><?php endif; ?><form method="post"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="8" required><button>Create account</button></form><p>Have an account? <a href="/login.php">Login</a></p></div></main></body></html>
